  break;

case POS_FIGHTING:
  send_to_char(ch, "Rest while fighting?  Are you MAD?\r\n");
  break;

default:
  send_to_char(ch, "You stop floating around, and stop to rest your tired bones.\r\n");
  act("$n stops floating around, and rests.", FALSE, ch, 0, 0, TO_ROOM);
  GET_POS(ch) = POS_RESTING;
  break;

case POS_RESTING:
  if (state == 1 && furniture) {
    place_char_on_furniture(ch, furniture);
    act("You lie down upon $p and fall asleep.", TRUE, ch, furniture, 0, TO_CHAR);
    act("$n lies down upon $p and falls asleep.", TRUE, ch, furniture, 0, TO_ROOM);
  } else {
    send_to_char(ch, "You go to sleep.\r\n");
    act("$n lies down and falls asleep.", TRUE, ch, 0, 0, TO_ROOM);
  }
  GET_POS(ch) = POS_SLEEPING;
  break;

case POS_SLEEPING:
  send_to_char(ch, "You are already sound asleep.\r\n");
  break;

case POS_FIGHTING:
  send_to_char(ch, "Sleep while fighting?  Are you MAD?\r\n");
  break;

  default:
    send_to_char(ch, "You stop floating around, and lie down to sleep.\r\n");
    act("$n stops floating around, and lie down to sleep.",
	TRUE, ch, 0, 0, TO_ROOM);
    GET_POS(ch) = POS_SLEEPING;
    break;

    default: return "unknown";
  }
}

