	else if (!strcmp(tag, "Thr3"))	GET_SAVE(ch, 2)		= atoi(line);
	else if (!strcmp(tag, "Thr4"))	GET_SAVE(ch, 3)		= atoi(line);
	else if (!strcmp(tag, "Thr5"))	GET_SAVE(ch, 4)		= atoi(line);
	else if (!strcmp(tag, "Trns"))	GET_TRAINS(ch)		 = atoi(line);
	else if (!strcmp(tag, "Titl"))	GET_TITLE(ch)		= strdup(line);
        else if (!strcmp(tag, "Trig") && CONFIG_SCRIPT_PLAYERS) {
          if ((t_rnum = real_trigger(atoi(line))) != NOTHING) {
            t = read_trigger(t_rnum);
          if (!SCRIPT(ch))
            CREATE(SCRIPT(ch), struct script_data, 1);
          add_trigger(SCRIPT(ch), t, -1);
          }
         }
	break;

      case 'V':
	     if (!strcmp(tag, "Vars"))	read_saved_vars_ascii(fl, ch, atoi(line));
      break;

      case 'W':
	     if (!strcmp(tag, "Wate"))	GET_WEIGHT(ch)		= atoi(line);
	else if (!strcmp(tag, "Wimp"))	GET_WIMP_LEV(ch)	= atoi(line);
	else if (!strcmp(tag, "Wis "))	ch->real_abils.wis	= atoi(line);
	break;

      default:
        sprintf(buf, "SYSERR: Unknown tag %s in pfile %s", tag, name);
      }
    }
  }

    if (!armor_seen && legacy_ac_seen)
      GET_AC(ch) = legacy_ac_to_armor(legacy_ac_raw);

    if (money_seen && __loaded_money_gold >= 0) {
      GET_MONEY(ch) = normalize_currency_units(__loaded_money_gold);
    } else if (!money_seen && __loaded_gold_units >= 0) {
      GET_MONEY(ch) = (long long)__loaded_gold_units;
    }

    if (bank_money_seen && __loaded_bank_money >= 0)
      GET_BANK_MONEY(ch) = normalize_currency_units(__loaded_bank_money);

  if (upgrade_legacy_immortal_levels(ch))
      mudlog(CMP, LVL_IMMORT, TRUE, "%s converted to updated immortal tier (level %d).", GET_NAME(ch), GET_LEVEL(ch));
  clamp_player_exp_to_level(ch);

  /* Ensure persisted base stats stay within the creation caps on load. */
  clamp_base_stats(ch);

  /* Keep any existing characters in sync with their class spell/skill lists. */
  ensure_class_abilities(ch);
  classtrack_ensure_study_skill(ch);

  if (!*GET_SOFT_CLASS_TITLE(ch))
    strlcpy(GET_SOFT_CLASS_TITLE(ch), "Adventurer", sizeof(ch->player_specials->saved.soft_class_title));

  for (i = 0; i < MAX_SHADOW_ROSTER; i++)
    SHADOW_SLOT_ACTIVE(ch, i) = 0;

  affect_total(ch);

  /* initialization for imms */
  if (GET_LEVEL(ch) >= LVL_IMMORT) {
    for (i = 1; i <= MAX_SKILLS; i++)
      GET_SKILL(ch, i) = 100;
    GET_COND(ch, HUNGER) = -1;
    GET_COND(ch, THIRST) = -1;
    GET_COND(ch, DRUNK) = -1;
  }
  fclose(fl);
  DEFAULT_RACE_ON_LOAD(ch);
  return(id);
}

